/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useMemo } from 'react'
import { Button, Col, Form, Icon, Input, Typography } from 'antd'
import { RowWithMargin } from '../../../../../CommonComponents'
import { useDownloadFileFromGcs } from '../../../../../state/hooks'
import FileUploadOnGcsV2 from '../../../../../../../../components/FileUploadOnGcsV2'
import lodash from 'lodash'
import PermissionCheckerV2 from '../../../../../../../../components/permissionCheckerV2'
import PropTypes from 'prop-types'
import { acceptStringBasedOnFileTypeForUpload } from './constants'
import { useDownloadAllZipDocuments } from '../../../../../state/ClaimDetail/hooks/useClaimDetails'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { downloadDataFromUrl } from '../../../../../../../../helpers/utility'

const { Text } = Typography

const ClaimUpdateForm = ({ claimNumber, getFieldDecorator, detailData, form, onSubmit }) => {
  const { forms: { bank_details: bankDetails, ...remainingForms }, notes, user_remark: userRemark } = (!lodash.isEmpty(detailData) && detailData) || { forms: { bank_details: undefined } }
  const bankDetailArray = useMemo(() => Object.values(bankDetails || {}), [bankDetails])
  const remainingFormsArray = useMemo(() => Object.entries(remainingForms || {}), [remainingForms])
  const { downloadRequest } = useDownloadFileFromGcs()
  const { downloadAllDocumentsRequest, downloadAllDocumentsData } = useDownloadAllZipDocuments()
  const [{ downloadAllDocumentsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  useEffect(() => {
    if (downloadAllDocumentsStatus === 'success' && downloadAllDocumentsData?.url) {
      downloadDataFromUrl(downloadAllDocumentsData.url)
      resetError(['downloadAllDocumentsStatus'])
    }
  }, [downloadAllDocumentsData, downloadAllDocumentsStatus])

  useEffect(() => {
    if (notes) {
      form.setFieldsValue({ notes })
    }
    if (userRemark) {
      form.setFieldsValue({ 'remarks_data.user_remark': userRemark })
    }
  }, [detailData])

  return (
    <Form
      onSubmit={onSubmit}
    >
      {
        bankDetailArray.map((bankDetail, index) => (
          <RowWithMargin key={index} gutter={16}>
            <Col span={8}><Text strong>{bankDetail.display_name}</Text></Col>
            <Col span={8}>{bankDetail.value}</Col>
          </RowWithMargin>
        ))
      }
      {
        remainingFormsArray.map(([formGroupName, formGroupData], index) => (
          Object.entries(formGroupData).map(([formItemName, formItemData], index) => formItemData.type === 'file'
            ? (
              <RowWithMargin key={index} gutter={16}>
                <Col span={8}><Text strong>{formItemData.display_name}</Text></Col>
                <Col span={4}>
                  <Button
                    className='no-padding'
                    type='link'
                    disabled={!formItemData?.value}
                    onClick={() => {
                      const fileName = formItemData?.value?.split(':')[2]
                      downloadRequest({
                        action_type: 'GET',
                        identifier: 'claim',
                        file_name: fileName
                      })
                    }}
                  >
                    Download <Icon type='download' />
                  </Button>
                </Col>
                <PermissionCheckerV2 requiredPermission='ops.eb_update_claim'>
                  <Col span={6}>
                    <FileUploadOnGcsV2
                      getFieldDecorator={getFieldDecorator}
                      identifier='claim'
                      form={form}
                      name={`forms.${formGroupName}.${formItemName}`}
                      // maxFileAllowed={formItemData?.is_multiple_value_allowed ? undefined : 1}
                      maxFileAllowed={1}
                      buttonText='Re Upload'
                      multiple={formItemData?.is_multiple_value_allowed}
                      accept={formItemData?.file_formats && acceptStringBasedOnFileTypeForUpload(formItemData?.file_formats)}
                    />
                    <Text disabled>Allowed file formats are - {formItemData?.file_formats?.join(', ')}</Text>
                  </Col>
                  {/* <Col span={4}>
                    <Text>Allowed file formats are - {formItemData?.file_formats?.join(', ')}</Text>
                  </Col> */}
                </PermissionCheckerV2>
              </RowWithMargin>
              )
            : (
              <RowWithMargin key={index} gutter={16}>
                <Col span={8}><Text strong>{formItemData.display_name}</Text></Col>
                <Col span={8}>{formItemData.value}</Col>
              </RowWithMargin>
              ))
        ))
      }
      <RowWithMargin>
        <Col span={8}><Text strong>Notes</Text></Col>
        <Col span={8}>
          <Form.Item>
            {
              getFieldDecorator('notes', {})(<Input.TextArea rows={4} />)
            }
          </Form.Item>
        </Col>
      </RowWithMargin>
      <RowWithMargin>
        <Col span={8}><Text strong>Participant Remarks (akan tampil di EB app peserta)</Text></Col>
        <Col span={8}>
          <Form.Item>
            {
              getFieldDecorator('remarks_data.user_remark', {
                validateStatus: 'onBlur',
                rules: [
                  {
                    max: 500,
                    message: 'Maximum number of characters can be 500'
                  }
                ]
              })(<Input.TextArea rows={4} />)
            }
          </Form.Item>
        </Col>
      </RowWithMargin>
      <RowWithMargin>
        <Col offset={8}>
          <PermissionCheckerV2 requiredPermission='ops.eb_update_claim'>
            <Button type='primary' htmlType='submit'>Submit</Button>
          </PermissionCheckerV2>
          <Button
            type='primary'
            className='m-5'
            onClick={() => downloadAllDocumentsRequest({ claim_id: detailData?.claim_id })}
          >
            Download Documents
          </Button>
        </Col>
      </RowWithMargin>
    </Form>
  )
}
export default ClaimUpdateForm

ClaimUpdateForm.propTypes = {
  getFieldDecorator: PropTypes.func.isRequired,
  form: PropTypes.object.isRequired,
  onSubmit: PropTypes.func.isRequired
}
