import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useClaimDetail = () => {
  const [{ claimDetailData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const claimDetailRequest = (payload = {}) => {
    callApi(actions.getClaimDetail({ query: payload }))
  }

  return {
    claimDetailRequest,
    claimDetailData
  }
}

export const useUpdateClaim = () => {
  const [{ updateClaimData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const updateClaimRequest = (payload = {}) => {
    callApi(actions.updateClaim({ body: payload }))
  }
  return { updateClaimRequest, updateClaimData }
}

export const useDownloadAllZipDocuments = () => {
  const [{ downloadAllDocumentsData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const downloadAllDocumentsRequest = (payload = {}) => {
    callApi(actions.downloadAllDocuments({ query: payload }))
  }
  return { downloadAllDocumentsRequest, downloadAllDocumentsData }
}
