/* eslint-disable react-hooks/exhaustive-deps */
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Form, message, Spin } from 'antd'
import React, { useEffect } from 'react'
import { useHistory, useParams } from 'react-router'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { useClaimDetail, useUpdateClaim } from '../../../state/ClaimDetail/hooks/useClaimDetails'
import ClaimUpdateForm from './components/DetailForm'
import lodash from 'lodash'

const ClaimDetail = ({ form }) => {
  const { getFieldDecorator } = form
  const { claimDetailRequest, claimDetailData } = useClaimDetail()
  const { updateClaimRequest } = useUpdateClaim()
  const [{ CLAIM_DETAIL_LOADER, UPDATE_CLAIM_LOADER }] = useLoaderContextValue()
  const [{
    CLAIM_DETAIL_ERROR,
    claimDetailStatus,
    claimDetailErrorData,
    DOWNLOAD_FILE_FROM_GCS_ERROR,
    downloadFileFromGcsStatus,
    UPDATE_CLAIM_ERROR,
    updateClaimStatus,
    DOWNLOAD_ALL_DOCUMENTS_ERROR,
    downloadAllDocumentsStatus
  }] = useErrorContextValue()
  const { resetError } = useResetError()
  const history = useHistory()
  const { claimId } = useParams()

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        for (const formItemGroupKey in values?.forms) {
          for (const formItemKey in values.forms[formItemGroupKey]) {
            if (Array.isArray(values.forms[formItemGroupKey][formItemKey])) {
              values.forms[formItemGroupKey][formItemKey] = values.forms[formItemGroupKey][formItemKey][0]?.url
              // if (claimDetailData.forms[formItemGroupKey][formItemKey].is_multiple_value_allowed) {
              //   values.forms[formItemGroupKey][formItemKey] = values.forms[formItemGroupKey][formItemKey].map(({ url }) => url)
              // } else {
              //   values.forms[formItemGroupKey][formItemKey] = values.forms[formItemGroupKey][formItemKey][0]?.url
              // }
            }
          }
        }
        updateClaimRequest(lodash.pickBy({ claim_id: claimDetailData.claim_id, ...values }))
      }
    })
  }

  useEffect(() => {
    if (updateClaimStatus === 'success') {
      message.success('Claim Updated Successfully.')
      form.resetFields()
      claimDetailRequest({ claim_id: claimId })
      resetError(['updateClaimStatus'])
    }
  }, [updateClaimStatus])

  useEffect(() => {
    claimDetailRequest({ claim_id: claimId })
  }, [])

  return (
    <EbEmptyPage history={history} path='/employee-benefits/claim-management/'>
      <Spin spinning={!!CLAIM_DETAIL_LOADER || !!UPDATE_CLAIM_LOADER}>
        {
          CLAIM_DETAIL_ERROR &&
            <div className='mb-5'>
              <Alert type='error' message={claimDetailErrorData?.message || claimDetailStatus} banner />
            </div>
        }
        {
          DOWNLOAD_FILE_FROM_GCS_ERROR &&
            <div className='mb-5'>
              <Alert type='error' message={downloadFileFromGcsStatus} banner />
            </div>
          }
        {
          UPDATE_CLAIM_ERROR &&
            <div className='mb-5'>
              <Alert type='error' message={updateClaimStatus} banner />
            </div>
        }
        {
          DOWNLOAD_ALL_DOCUMENTS_ERROR &&
            <div className='mb-5'>
              <Alert type='error' message={downloadAllDocumentsStatus} banner />
            </div>
        }
        <h2>Details</h2>
        <ClaimUpdateForm
          claimNumber={claimId}
          getFieldDecorator={getFieldDecorator}
          detailData={claimDetailData}
          form={form}
          onSubmit={handleSubmit}
        />
      </Spin>
    </EbEmptyPage>
  )
}
export default Form.create({ name: 'claim-update-form' })(ClaimDetail)
