
const acceptStringConfig = {
  pdf: 'application/pdf',
  jpg: 'image/*',
  png: 'image/*',
  doc: '.doc, docx',
  docx: '.doc, .docx'
}

export const acceptStringBasedOnFileTypeForUpload = (allowedFileFormats = []) => {
  const acceptStringSet = new Set()
  for (const allowedFileFormat of allowedFileFormats) {
    if (acceptStringConfig[allowedFileFormat]) {
      acceptStringSet.add(`${acceptStringConfig[allowedFileFormat]}`)
    }
  }
  return Array.from(acceptStringSet).join(', ')
}
