import actions from './actions'

const ClaimDetailReducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case actions.CLAIM_DETAIL:
    case actions.UPDATE_CLAIM:
    case actions.DOWNLOAD_ALL_DOCUMENTS:
      return { ...state, ...payload }
    default:
      return state
  }
}

export default ClaimDetailReducer
