import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  CLAIM_DETAIL_REQUEST: 'CLAIM_DETAIL_REQUEST',
  CLAIM_DETAIL: 'CLAIM_DETAIL',
  UPDATE_CLAIM_REQUEST: 'UPDATE_CLAIM_REQUEST',
  UPDATE_CLAIM: 'UPDATE_CLAIM',
  DOWNLOAD_ALL_DOCUMENTS_REQUEST: 'DOWNLOAD_ALL_DOCUMENTS_REQUEST',
  DOWNLOAD_ALL_DOCUMENTS: 'DOWNLOAD_ALL_DOCUMENTS',

  getClaimDetail: payload => ({
    type: actions.CLAIM_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getClaimDetail
    }
  }),
  updateClaim: payload => ({
    type: actions.UPDATE_CLAIM_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateClaim
    }
  }),
  downloadAllDocuments: payload => ({
    type: actions.DOWNLOAD_ALL_DOCUMENTS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.downloadAllClaimDocumentsZip
    }
  })
}

export default actions
